process.env.USE_MOCK_BLOCKCHAIN = 'true';
process.env.USE_MOCK_IPFS = 'true';
process.env.USE_MOCK_ARWEAVE = 'true';
process.env.USE_MOCK_WATERMARK = 'true';
process.env.USE_MOCK_AI = 'true';
process.env.USE_KMS = 'false';
process.env.DEV_ENCRYPTION_KEY = 'a'.repeat(64);
process.env.NODE_ENV = 'test';

const request = require('supertest');
const express = require('express');
const crypto = require('crypto');
const { SiweMessage } = require('siwe');

const marketplaceRouter = require('../../src/routes/marketplace');
const blockchainService = require('../../src/services/blockchain');

// Helper: create a mock SIWE auth token using the SiweMessage constructor for correct format
function createMockAuthToken(address) {
  const siwe = new SiweMessage({
    domain: 'localhost',
    address: address,
    statement: 'Sign in to NFTmarket',
    uri: 'http://localhost:3000',
    version: '1',
    chainId: 31337,
    nonce: 'test1234',
    issuedAt: new Date().toISOString(),
  });
  const message = siwe.toMessage();
  const signature = '0x' + crypto.createHash('sha256').update(message).digest('hex');
  return Buffer.from(JSON.stringify({ message, signature })).toString('base64');
}

// Mount the router on a test app (tests it as a router, not via the full app)
function createTestApp() {
  const app = express();
  app.use(express.json());
  app.use('/api/marketplace', marketplaceRouter);
  app.use((err, req, res, next) => {
    res.status(err.status || 500).json({ error: err.message, code: err.code || 'INTERNAL_ERROR' });
  });
  return app;
}

const WALLET = '0x1234567890123456789012345678901234567890';

/** Mint a token for marketplace tests */
async function mintToken(imageHash) {
  const [r] = await blockchainService.reserveTokenId();
  const [result] = await blockchainService.mint(
    r.tokenId, WALLET, 'ipfs://uri', imageHash || '0xhash' + Date.now(), 'ipfs://img'
  );
  return r.tokenId;
}

describe('Marketplace router interface contract', () => {
  let app;
  let authToken;

  beforeAll(() => {
    app = createTestApp();
    authToken = createMockAuthToken(WALLET);
  });

  beforeEach(() => {
    blockchainService.resetMock();
  });

  // ── Module export ──

  test('exports an Express router', () => {
    expect(typeof marketplaceRouter).toBe('function');
    // Express routers have a stack property
    expect(Array.isArray(marketplaceRouter.stack)).toBe(true);
  });

  // ── Public GET routes ──

  test('GET / returns listings array and contract info', async () => {
    const res = await request(app).get('/api/marketplace');

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('listings');
    expect(Array.isArray(res.body.listings)).toBe(true);
    expect(res.body).toHaveProperty('contract');
    expect(res.body.contract).toHaveProperty('name');
    expect(res.body.contract).toHaveProperty('address');
    expect(res.body.contract).toHaveProperty('chainId');
  });

  test('GET /eip712/domain returns domain object', async () => {
    const res = await request(app).get('/api/marketplace/eip712/domain');

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('domain');
    expect(res.body.domain).toHaveProperty('name');
    expect(res.body.domain).toHaveProperty('version');
    expect(res.body.domain).toHaveProperty('chainId');
    expect(res.body.domain).toHaveProperty('verifyingContract');
  });

  test('GET /nonce/:address returns nonce', async () => {
    const res = await request(app).get(`/api/marketplace/nonce/${WALLET}`);

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('address', WALLET);
    expect(res.body).toHaveProperty('nonce');
  });

  test('GET /:tokenId returns listing details for minted token', async () => {
    const tokenId = await mintToken('0xunique1');

    // List the token first
    await blockchainService.listToken(tokenId, '1000000000000000000', 0, '0xlicensehash', 0, '0x' + 'ab'.repeat(65), WALLET);

    const res = await request(app).get(`/api/marketplace/${tokenId}`);

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('listed', true);
    expect(res.body).toHaveProperty('tokenId');
    expect(res.body).toHaveProperty('listings');
    expect(Array.isArray(res.body.listings)).toBe(true);
  });

  test('GET /:tokenId returns listed:false for unlisted token', async () => {
    const tokenId = await mintToken('0xunique2');

    const res = await request(app).get(`/api/marketplace/${tokenId}`);

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('listed', false);
  });

  // ── Authenticated POST routes ──

  test('POST /list requires authentication', async () => {
    const res = await request(app)
      .post('/api/marketplace/list')
      .send({ tokenId: 0, priceEth: '1.0', licenseType: 'display' });

    expect(res.status).toBe(401);
  });

  test('POST /list returns typed data and contract call', async () => {
    const tokenId = await mintToken('0xunique3');

    const res = await request(app)
      .post('/api/marketplace/list')
      .set('Authorization', `Bearer ${authToken}`)
      .send({ tokenId, priceEth: '1.0', licenseType: 'display' });

    expect(res.status).toBe(200);
    expect(res.body.success).toBe(true);
    expect(res.body).toHaveProperty('typedData');
    expect(res.body.typedData).toHaveProperty('types');
    expect(res.body.typedData).toHaveProperty('primaryType', 'ListingOffer');
    expect(res.body.typedData).toHaveProperty('domain');
    expect(res.body.typedData).toHaveProperty('message');
    expect(res.body).toHaveProperty('contractCall');
    expect(res.body.contractCall.method).toBe('list');
    expect(res.body).toHaveProperty('summary');
  });

  test('POST /buy requires authentication', async () => {
    const res = await request(app)
      .post('/api/marketplace/buy')
      .send({ tokenId: 0, licenseType: 'display' });

    expect(res.status).toBe(401);
  });

  test('POST /delist requires authentication', async () => {
    const res = await request(app)
      .post('/api/marketplace/delist')
      .send({ tokenId: 0, licenseType: 'display' });

    expect(res.status).toBe(401);
  });

  // ── EIP-712 types use shared module ──

  test('list typed data uses shared EIP-712 types', async () => {
    const { EIP712_DOMAIN_TYPE, LISTING_OFFER_TYPE } = require('../../src/shared/eip712-types');
    const tokenId = await mintToken('0xunique4');

    const res = await request(app)
      .post('/api/marketplace/list')
      .set('Authorization', `Bearer ${authToken}`)
      .send({ tokenId, priceEth: '1.0', licenseType: 'display' });

    expect(res.status).toBe(200);
    // Verify the types match the shared module
    expect(res.body.typedData.types.EIP712Domain).toEqual(EIP712_DOMAIN_TYPE);
    expect(res.body.typedData.types.ListingOffer).toEqual(LISTING_OFFER_TYPE);
  });

  // ── Validation ──

  test('POST /list validates missing tokenId', async () => {
    const res = await request(app)
      .post('/api/marketplace/list')
      .set('Authorization', `Bearer ${authToken}`)
      .send({ priceEth: '1.0', licenseType: 'display' });

    expect(res.status).toBe(400);
  });

  test('POST /list validates invalid license type', async () => {
    const tokenId = await mintToken('0xunique5');

    const res = await request(app)
      .post('/api/marketplace/list')
      .set('Authorization', `Bearer ${authToken}`)
      .send({ tokenId, priceEth: '1.0', licenseType: 'invalid' });

    expect(res.status).toBe(400);
  });

  test('POST /list validates ownership', async () => {
    const tokenId = await mintToken('0xunique6');
    // Use a different wallet
    const otherToken = createMockAuthToken('0xaAaAaAaaAaAaAaaAaAAAAAAAAaaaAaAaAaaAaaAa');

    const res = await request(app)
      .post('/api/marketplace/list')
      .set('Authorization', `Bearer ${otherToken}`)
      .send({ tokenId, priceEth: '1.0', licenseType: 'display' });

    expect(res.status).toBe(403);
    expect(res.body.code).toBe('NOT_OWNER');
  });
});
